// What a basket means depends entirely on the platform, and the difference is
// not cosmetic:
//
//   TikTok   real. TikTok Shop attaches catalogue products to a LIVE room and
//            the viewer taps the basket to buy without leaving the stream.
//   Facebook gone. Meta ended Live Shopping product tagging on 1 October 2022
//            (Instagram followed in March 2023). There is nothing to pin to.
//            The list is the host's own running order and the comments are
//            the till, which is what this workflow then reads.
const body = $input.first().json.body;
const session = body.session ?? {};
const basket = (session.basket ?? []).filter((b) => b.state === 'PIN_PENDING');

if (session.platform !== 'tiktok') {
  return basket.map((b) => ({ json: {
    session_id: session.id, product_id: b.product_id, slot: b.slot,
    // Not a failure: the item is on the host's list and claims against it
    // work. It simply is not tappable, and the dashboard already says so.
    state: 'PINNED', external_id: null, host_list_only: true,
  } }));
}
return basket.map((b) => ({ json: {
  session_id: session.id, business_id: session.business_id,
  account_id: session.account_id, room_id: session.external_id,
  product_id: b.product_id, slot: b.slot,
  live_price: b.live_price ?? b.shelf_price, name: b.name,
} }));

// TikTok Shop: attach the product to the LIVE room's showcase. The id it hands
// back is what the basket row stores, so the item can be taken down again.
const crypto = require('crypto');
const creds = $('Live Credentials').item.json.credentials;
const item = $('Basket To Pin').item.json;
if (!creds?.access_token || !creds?.shop_cipher) {
  return [{ json: { ...item, state: 'FAILED',
    error: 'TIKTOK access_token or shop_cipher is not set for this shop' } }];
}
if (!item.room_id) {
  return [{ json: { ...item, state: 'FAILED',
    error: 'the stream is not up yet, so there is no room to pin to' } }];
}
const host = creds.host || 'https://open-api.tiktokglobalshop.com';
const path = `/live/202309/rooms/${item.room_id}/products`;
const body = JSON.stringify({ product_id: String(item.product_id),
                              display_order: item.slot });
const params = { app_key: creds.app_key, shop_cipher: creds.shop_cipher,
                 timestamp: String(Math.floor(Date.now() / 1000)), version: '202309' };
const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
const base = creds.app_secret + path + sorted + body + creds.app_secret;
const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');
return [{ json: { ...item, url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
  payload: JSON.parse(body), access_token: creds.access_token } }];

const item = $('Pin On TikTok Live').item.json;
if (item.state === 'FAILED') return [{ json: item }];
const res = $input.item.json;
const body = res.body ?? res;
const ok = (res.statusCode ?? 200) < 400 && (body?.code ?? 0) === 0;
return [{ json: {
  session_id: item.session_id, product_id: item.product_id,
  state: ok ? 'PINNED' : 'FAILED',
  external_id: body?.data?.id ?? null,
  error: ok ? null : (body?.message || `TikTok refused item ${item.slot}`),
} }];

// An armed session is one a human approved: they read the exact line the
// desk will send a claimer and said yes to it. That approval is what the
// polling lane below checks before it answers anybody.
//
// Arming is not going live. The seller starts their own stream in the
// platform's app and then connects the room from the dashboard, which is
// what moves the session to LIVE and gives it a room id. Setting LIVE
// here instead used to skip both, and stamped every session with one
// room id out of the environment — the same id for every business on the
// deployment.
const body = $input.first().json.body;
const session = body.session ?? {};
return [{ json: { session_id: session.id, business_id: session.business_id,
  platform: session.platform, armed: true, status: session.status } }];

// Only rooms a human armed and nobody has paused. The backend already filters
// to LIVE, but it is cheap to be sure before spending a call on a room that
// must not be answered.
return ($input.first().json.sessions ?? [])
  .filter((s) => s.status === 'LIVE' && s.armed)
  .map((s) => ({ json: {
    session_id: s.id, business_id: s.business_id, account_id: s.account_id,
    platform: s.platform, room_id: s.external_id,
    hold_minutes: s.hold_minutes,
    slots: (s.basket ?? []).filter((b) => b.state === 'PINNED').map((b) => b.slot),
  } }));

// Two numbers and a list of comments, from whichever API the platform has.
//
//   TikTok   live/202309/rooms/{id} carries viewers, likes and the basket
//            taps — "product clicks" — which is the one metric Facebook has
//            no equivalent for, because Facebook has no basket.
//   Facebook the Live video node gives live_views and the comments edge. The
//            comments are what matters: they are where the selling happens.
const crypto = require('crypto');
const creds = $('Room Credentials').item.json.credentials ?? {};
const item = $('One Room Each').item.json;

if (!item.room_id) {
  return [{ json: { ...item, skipped: true, error: 'no room id yet' } }];
}

if (item.platform === 'tiktok') {
  if (!creds.access_token) {
    return [{ json: { ...item, skipped: true, error: 'TIKTOK access_token is not set' } }];
  }
  const host = creds.host || 'https://open-api.tiktokglobalshop.com';
  const path = `/live/202309/rooms/${item.room_id}`;
  const params = { app_key: creds.app_key, shop_cipher: creds.shop_cipher,
                   timestamp: String(Math.floor(Date.now() / 1000)), version: '202309' };
  const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
  const base = creds.app_secret + path + sorted + creds.app_secret;
  const sign = crypto.createHmac('sha256', creds.app_secret).update(base).digest('hex');
  return [{ json: { ...item,
    url: `${host}${path}?${new URLSearchParams({ ...params, sign })}`,
    access_token: creds.access_token } }];
}

if (!creds.page_access_token) {
  return [{ json: { ...item, skipped: true, error: 'META page_access_token is not set' } }];
}
const fields = 'live_views,status,comments.limit(50){from,message,created_time,id}';
return [{ json: { ...item,
  url: `https://graph.facebook.com/v21.0/${item.room_id}`
     + `?fields=${encodeURIComponent(fields)}`
     + `&access_token=${creds.page_access_token}` } }];

// One metrics sample, and one item per comment that might be a purchase.
const item = $('One Room Each').item.json;
const body = $input.item.json;
const out = [];

if (item.platform === 'tiktok') {
  const d = body?.data ?? {};
  out.push({ json: { kind: 'metrics', session_id: item.session_id,
    viewers: Number(d.current_viewer_count ?? 0),
    likes: Number(d.like_count ?? 0),
    comments: Number(d.comment_count ?? 0),
    basket_opens: Number(d.product_click_count ?? 0),
    orders: Number(d.order_count ?? 0),
    revenue: Number(d.gmv ?? 0) } });
  for (const c of d.comments ?? []) {
    out.push({ json: { kind: 'comment', session_id: item.session_id,
      slots: item.slots, text: c.content,
      buyer_name: c.nickname, buyer_handle: c.user_id } });
  }
} else {
  out.push({ json: { kind: 'metrics', session_id: item.session_id,
    viewers: Number(body?.live_views ?? 0),
    likes: 0, comments: (body?.comments?.data ?? []).length,
    // Facebook has no basket to open, so this stays at nought rather than
    // being filled with a number that means something else.
    basket_opens: 0, orders: 0, revenue: 0 } });
  for (const c of body?.comments?.data ?? []) {
    out.push({ json: { kind: 'comment', session_id: item.session_id,
      slots: item.slots, text: c.message,
      buyer_name: c.from?.name, buyer_handle: c.from?.id } });
  }
}
return out;

// The link the claimer pays on. Nobody pays this app: on TikTok the cart
// is the platform's own, and on Facebook — with Live Shopping gone — the
// seller sends the buyer to their own checkout, which is why this needs
// LIVE_CHECKOUT_BASE rather than pretending a Facebook basket exists.
//
// Neither piece is invented when it is missing. A claim nobody could be
// told about is reported as exactly that: the hold stands, and the log
// names the variable that was not set. A silently skipped reply looks
// like an answered buyer, which is worse than an obvious gap.
const claim = $input.item.json;
const base = ($env.LIVE_CHECKOUT_BASE || '').replace(/\/$/, '');
const replyTo = $env.LIVE_REPLY_WEBHOOK_URL || '';
const missing = [];
if (!base) missing.push('LIVE_CHECKOUT_BASE');
if (!replyTo) missing.push('LIVE_REPLY_WEBHOOK_URL');
if (missing.length) {
  return [{ json: { ...claim, sendable: false,
    error: `${missing.join(' and ')} not set, so the claimer was told nothing` } }];
}
const url = `${base}/${claim.claim_id}`;
return [{ json: { ...claim, sendable: true, checkout_url: url, reply_to: replyTo,
  // The blank the approved sentence was written around, filled in now and
  // only now. Nothing else in the line is touched.
  reply: String(claim.reply_template ?? '').replaceAll('{checkout_url}', url) } }];
